/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import * as readline from 'readline'
import { Parser } from './parser.js'
import { Limiter } from './limiter.js'

async function main() {
  // Validate arguments
  if (process.argv.length !== 3) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const mode = process.argv[2]
  if (mode !== 'replay' && mode !== 'summary') {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  try {
    // Read all stdin lines
    const lines = []
    const rl = readline.createInterface({
      input: process.stdin,
      output: undefined,
      terminal: false
    })

    for await (const line of rl) {
      lines.push(line)
    }

    // Remove trailing empty line if present (from trailing newline)
    if (lines.length > 0 && lines[lines.length - 1] === '') {
      lines.pop()
    }

    // Parse the configuration
    const parser = new Parser(lines)
    const { buckets, windows, routes, events } = parser.parse()

    // Create limiter and process events
    const limiter = new Limiter(buckets, windows, routes)
    const results = limiter.processEvents(events, mode)

    // Output results
    for (const line of results) {
      process.stdout.write(line + '\n')
    }

    process.exit(0)
  } catch (err) {
    process.stderr.write(err.message + '\n')
    process.exit(2)
  }
}

main()
"}

