const VALID_CHARS = /^[A-Za-z0-9_.\/:@-]*$/
const VALID_NAME_CHARS = /^[A-Za-z0-9_.\/:@-]+$/

export class Parser {
  constructor(lines) {
    this.lines = lines
    this.buckets = new Map()
    this.windows = new Map()
    this.routes = []
    this.events = []
    this.policyNames = new Set()
    this.routePrefixes = new Set()
    this.firstEventLineNum = null
  }

  parse() {
    for (let lineNum = 0; lineNum < this.lines.length; lineNum++) {
      const line = this.lines[lineNum]
      const trimmed = line.trim()

      // Skip empty lines and comments
      if (!trimmed || trimmed.startsWith('#')) {
        continue
      }

      // Split on runs of whitespace
      const tokens = trimmed.split(/\s+/)
      const directive = tokens[0]

      // Record first event line
      if (directive === 'event' && this.firstEventLineNum === null) {
        this.firstEventLineNum = lineNum + 1
      }

      if (directive === 'bucket') {
        this.parseBucket(tokens, lineNum + 1)
      } else if (directive === 'window') {
        this.parseWindow(tokens, lineNum + 1)
      } else if (directive === 'route') {
        this.parseRoute(tokens, lineNum + 1)
      } else if (directive === 'event') {
        this.parseEvent(tokens, lineNum + 1)
      } else {
        throw new Error(`error: line ${lineNum + 1}: unknown directive ${directive}`)
      }
    }

    return {
      buckets: this.buckets,
      windows: this.windows,
      routes: this.routes,
      events: this.events
    }
  }

  parseBucket(tokens, lineNum) {
    if (this.firstEventLineNum !== null) {
      throw new Error(`error: line ${lineNum}: declarations must come before the first event`)
    }

    if (tokens.length !== 5) {
      throw new Error(`error: line ${lineNum}: expected bucket <name> <capacity> <refill> <per>`)
    }

    const name = tokens[1]
    const capacity = this.parseInteger(tokens[2], 'capacity', 1, lineNum)
    const refill = this.parseInteger(tokens[3], 'refill', 0, lineNum)
    const per = this.parseInteger(tokens[4], 'per', 1, lineNum)

    this.validateName(name, lineNum)

    if (this.policyNames.has(name)) {
      throw new Error(`error: line ${lineNum}: policy ${name} is declared twice`)
    }

    this.policyNames.add(name)
    this.buckets.set(name, { capacity, refill, per })
  }

  parseWindow(tokens, lineNum) {
    if (this.firstEventLineNum !== null) {
      throw new Error(`error: line ${lineNum}: declarations must come before the first event`)
    }

    if (tokens.length !== 4) {
      throw new Error(`error: line ${lineNum}: expected window <name> <limit> <span>`)
    }

    const name = tokens[1]
    const limit = this.parseInteger(tokens[2], 'limit', 0, lineNum)
    const span = this.parseInteger(tokens[3], 'span', 1, lineNum)

    this.validateName(name, lineNum)

    if (this.policyNames.has(name)) {
      throw new Error(`error: line ${lineNum}: policy ${name} is declared twice`)
    }

    this.policyNames.add(name)
    this.windows.set(name, { limit, span })
  }

  parseRoute(tokens, lineNum) {
    if (this.firstEventLineNum !== null) {
      throw new Error(`error: line ${lineNum}: declarations must come before the first event`)
    }

    if (tokens.length < 3) {
      throw new Error(`error: line ${lineNum}: expected route <prefix> <policy>...`)
    }

    const prefix = tokens[1]
    const policies = tokens.slice(2)

    this.validatePrefix(prefix, lineNum)

    if (this.routePrefixes.has(prefix)) {
      throw new Error(`error: line ${lineNum}: prefix ${prefix} is routed twice`)
    }

    // Validate that all policies exist
    for (const policy of policies) {
      if (!this.policyNames.has(policy)) {
        throw new Error(`error: line ${lineNum}: unknown policy ${policy}`)
      }
    }

    this.routePrefixes.add(prefix)
    this.routes.push({ prefix, policies })
  }

  parseEvent(tokens, lineNum) {
    if (tokens.length !== 3) {
      throw new Error(`error: line ${lineNum}: expected event <tick> <key>`)
    }

    const tick = this.parseInteger(tokens[1], 'tick', 0, lineNum)
    const key = tokens[2]

    this.validateKey(key, lineNum)

    // Check tick is not going backwards
    if (this.events.length > 0) {
      const lastTick = this.events[this.events.length - 1].tick
      if (tick < lastTick) {
        throw new Error(`error: line ${lineNum}: tick ${tick} is before tick ${lastTick}`)
      }
    }

    this.events.push({ tick, key, lineNum })
  }

  parseInteger(str, field, minimum, lineNum) {
    // Check for leading zeros (not allowed unless it's exactly "0")
    if (str !== '0' && str.startsWith('0')) {
      throw new Error(`error: line ${lineNum}: ${field} must be an integer of at least ${minimum}`)
    }

    // Check it's a valid decimal number
    if (!/^\d+$/.test(str)) {
      throw new Error(`error: line ${lineNum}: ${field} must be an integer of at least ${minimum}`)
    }

    const value = parseInt(str, 10)

    if (value < minimum) {
      throw new Error(`error: line ${lineNum}: ${field} must be an integer of at least ${minimum}`)
    }

    return value
  }

  validateName(name, lineNum) {
    if (!VALID_NAME_CHARS.test(name)) {
      throw new Error(`error: line ${lineNum}: invalid policy name ${name}`)
    }
  }

  validatePrefix(prefix, lineNum) {
    if (!VALID_NAME_CHARS.test(prefix)) {
      throw new Error(`error: line ${lineNum}: invalid route prefix ${prefix}`)
    }
  }

  validateKey(key, lineNum) {
    if (!VALID_NAME_CHARS.test(key)) {
      throw new Error(`error: line ${lineNum}: invalid key ${key}`)
    }
  }
}
