      const route = this.findRoute(key)

      if (route === null) {
        // No route matches, always allow
        results.push(`${tick} ${key} allow`)

        if (mode === 'summary') {
          if (!keyStats.has(key)) {
            keyStats.set(key, { allowed: 0, denied: 0 })
          }
          keyStats.get(key).allowed++
          totalAllowed++
        }
